package io.tuji.app;
import org.junit.Test;import static org.junit.Assert.*;import android.app.*;import android.content.*;import android.os.*;import androidx.test.platform.app.InstrumentationRegistry;
public class ViewerTest{@Test public void viewerCopyZoomAndTutorial()throws Exception{Instrumentation i=InstrumentationRegistry.getInstrumentation();MainActivity a=(MainActivity)i.startActivitySync(new Intent(i.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1500);i.runOnMainSync(()->{assertEquals(5,a.navItems.size());a.tab=4;a.render();assertNotNull(a.tutorial);a.tutorial.chapter=2;a.tutorial.render();assertTrue("tutorial back",a.tutorial.back());a.tab=2;a.render();PhotoStore.Photo p=a.app.gallery.located().get(0);PhotoDetail d=new PhotoDetail(a,p);d.show();d.expanded=true;d.layoutInfo();assertEquals("30.5126304444",PhotoDetail.number(30.512630444444));assertEquals("-0.5000000000",PhotoDetail.number(-.5));assertEquals("0.0000000000",PhotoDetail.number(0));d.copy(2);assertTrue("clipboard pair",((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).getPrimaryClip().getItemAt(0).getText().toString().contains(","));d.image.zoom=3;d.image.cx=.4f;Bundle state=d.state();assertEquals(3,state.getFloat("zoom"),.01);d.onBackPressed();assertFalse(d.expanded);d.dismiss();});i.runOnMainSync(a::finish);}}
